/*
# Add Home & Living products

1. New products
- Adds 20 home furniture, storage, decor, textile and bedding products to the existing `products` catalog under the `home-living` category.
- Each product uses the uploaded Amazon-style photos stored in the public images folder.

2. Modified data
- Only the `products` table is written to. Existing products are untouched.
- Uses deterministic slugs and SKUs (HOME-001 to HOME-020) so this migration can be safely re-run.

3. Security
- No tables, permissions, or row-level security policies are changed.

4. Important notes
- Where the source listed a price range, the lower end of the range is used.
- Product 17 and product 4 have fewer photos than the other products because not all of their photos were uploaded.
*/

INSERT INTO products (slug, name, category, subcategory, short_description, description, price, sku, sizes, colors, images, stock, status, audience, is_new, is_featured, is_best_seller) VALUES
('queen-metal-platform-bed-frame', 'Queen Metal Platform Bed Frame', 'home-living', 'Furniture', 'Sturdy queen platform bed frame with a low-profile metal base.', 'A queen metal platform bed frame with a clean, low-profile silhouette. Sturdy steel construction and no box spring required.', 55.99, 'HOME-001', ARRAY[]::text[], ARRAY['Black'], ARRAY['/images/718uzIxv2FL._AC_SL1500_.jpg','/images/71CsR0Rgx3L._AC_SL1500_.jpg','/images/810sivEpuPL._AC_SL1500_.jpg','/images/81CKjqG7kBL._AC_SL1500_.jpg'], 50, 'active', 'all', false, false, false),
('8-drawer-bedroom-dresser', '8-Drawer Bedroom Dresser', 'home-living', 'Furniture', 'Fabric-drawer dresser with eight roomy storage bins.', 'An 8-drawer bedroom dresser with sturdy fabric drawers and a wide top surface. Ample room for clothing, linens and accessories.', 36.28, 'HOME-002', ARRAY[]::text[], ARRAY['White'], ARRAY['/images/910B-vGgxaL._AC_SL1500_.jpg','/images/81TProHUG2L._AC_SL1500_.jpg','/images/81BNS5+J9JL._AC_SL1500_.jpg','/images/81KjqQAZ+fL._AC_SL1500_.jpg'], 50, 'active', 'all', false, false, false),
('modern-makeup-vanity-desk', 'Modern Makeup Vanity Desk', 'home-living', 'Furniture', 'Bright vanity desk with a mirror and drawers for daily beauty routines.', 'A modern makeup vanity desk with a clean white finish and a mirror for everyday beauty routines. Built-in storage keeps products within reach.', 89.00, 'HOME-003', ARRAY[]::text[], ARRAY['White'], ARRAY['/images/711FuJ8-0JL._AC_SL1500_.jpg','/images/71nD7adhL-L._AC_SL1500_.jpg','/images/71nl+sWnlvL._AC_SL1500_.jpg','/images/71X1-lJtT+L._AC_SL1500_.jpg'], 50, 'active', 'all', false, false, false),
('queen-cooling-mattress-topper', 'Queen Cooling Mattress Topper', 'home-living', 'Textiles', 'Plush pillow-top topper that refreshes an existing mattress.', 'A thick, plush queen mattress topper with a cooling fill and deep pockets. An affordable comfort upgrade for any existing mattress.', 39.99, 'HOME-004', ARRAY[]::text[], ARRAY['White'], ARRAY['/images/714xhV8IBkL._AC_SL1500_.jpg','/images/71DimnnrvlL._AC_SL1500_.jpg','/images/71Hs88mCJAL._AC_SL1500_.jpg'], 50, 'active', 'all', false, false, false),
('boneless-modular-sectional-sofa', 'Boneless Modular Sectional Sofa', 'home-living', 'Furniture', 'Four configurable corduroy modules with a wide backrest.', 'A 114-inch boneless modular sectional in soft cream corduroy. Four configurable modules and three pillows let you arrange it for any living room. No assembly needed.', 150.00, 'HOME-005', ARRAY[]::text[], ARRAY['Cream'], ARRAY['/images/81e-Y4X3ngL._AC_SL1500_.jpg','/images/81hKMixHcZL._AC_SL1500_.jpg','/images/81p5VC+sv6L._AC_SL1500_.jpg','/images/81XWhEqZDZL._AC_SL1500_.jpg'], 50, 'active', 'all', true, true, false),
('round-coffee-table-with-storage', 'Round Coffee Table with Storage', 'home-living', 'Furniture', 'Two-tier round coffee table with a marble-look top and open storage.', 'A two-tier round coffee table with a marble-look top and an open lower shelf. Decorative appeal and practical storage in one piece.', 100.00, 'HOME-006', ARRAY[]::text[], ARRAY['White Marble'], ARRAY['/images/719wRhbndJL._AC_SL1500_.jpg','/images/71Ogo1TaHGL._AC_SL1500_.jpg','/images/814oyzH5NBL._AC_SL1500_.jpg','/images/71Xmt5Tg-WL._AC_SL1500_.jpg'], 50, 'active', 'all', false, false, false),
('farmhouse-tv-stand', 'Farmhouse TV Stand', 'home-living', 'Furniture', 'Entertainment console with sliding barn doors and adjustable shelves.', 'A farmhouse TV stand that fits TVs up to 65 inches. Sliding barn doors, adjustable shelves and a storage cabinet keep media and clutter tidy.', 125.00, 'HOME-007', ARRAY[]::text[], ARRAY['White Walnut'], ARRAY['/images/61hN3RBnIQL._AC_SL1500_.jpg','/images/71Ionk5-9PL._AC_SL1500_.jpg','/images/71orODGI-tL._AC_SL1500_.jpg','/images/81N5nUg9MZL._AC_SL1500_.jpg'], 50, 'active', 'all', false, false, false),
('3-panel-folding-room-divider', '3-Panel Folding Room Divider', 'home-living', 'Decor', 'Lightweight rattan-look divider that adds privacy to any room.', 'A three-panel folding room divider with a natural rattan-look finish and a black frame. Creates privacy in apartments, studios and open-plan spaces.', 50.00, 'HOME-008', ARRAY[]::text[], ARRAY['Natural Rattan'], ARRAY['/images/71Ov9JCDQXL._AC_SL1500_.jpg','/images/71qpucXbs-L._AC_SL1500_.jpg','/images/81U3SNFGT4L._AC_SL1500_.jpg','/images/91LgVKpwkDL._AC_SL1500_.jpg'], 50, 'active', 'all', false, false, false),
('3-tier-shoe-rack', '3-Tier Shoe Rack', 'home-living', 'Decor', 'Budget-friendly three-tier metal rack for 12 to 15 pairs of shoes.', 'A three-tier metal shoe rack that holds 12 to 15 pairs. A compact entryway organizer that keeps footwear off the floor.', 9.99, 'HOME-009', ARRAY[]::text[], ARRAY['Black'], ARRAY['/images/716O1L+J2ZL._AC_SL1500_.jpg','/images/71FBnckmauL._AC_SL1500_.jpg','/images/81NfdTXvsFL._AC_SL1500_.jpg','/images/81SFL2o+rML._AC_SL1500_.jpg'], 50, 'active', 'all', false, false, false),
('over-the-door-shoe-organizer', 'Over-the-Door Shoe Organizer', 'home-living', 'Decor', 'Space-saving hanging organizer that fits over any standard door.', 'An over-the-door shoe organizer with multiple pockets that hangs on any standard door. Space-saving storage for shoes and small accessories.', 25.98, 'HOME-010', ARRAY[]::text[], ARRAY['Gray'], ARRAY['/images/81d9TGxykoL._AC_SL1500_.jpg','/images/81eCgNQ9mcL._AC_SL1500_.jpg','/images/81yI0nYDVlL._AC_SL1500_.jpg','/images/91js1VCEFQL._AC_SL1500_.jpg'], 50, 'active', 'all', false, false, false),
('upholstered-storage-ottoman-bench', 'Upholstered Storage Ottoman Bench', 'home-living', 'Furniture', 'Padded ottoman bench with hidden storage for seating and organizing.', 'An upholstered storage ottoman bench that doubles as seating and hidden storage. A soft, padded top works at the foot of a bed or in the living room.', 45.00, 'HOME-011', ARRAY[]::text[], ARRAY['Cream'], ARRAY['/images/81VidTuuSRL._AC_SL1500_.jpg','/images/91+SKxVmKIL._AC_SL1500_.jpg','/images/91WYq7Z3+0L._AC_SL1500_.jpg','/images/91xFm+Dv0CL._AC_SL1500_.jpg'], 50, 'active', 'all', false, false, false),
('floating-wall-shelves-set', 'Floating Wall Shelves Set', 'home-living', 'Decor', 'Set of solid wood-look floating shelves for display and storage.', 'A set of floating wall shelves in a natural wood-look finish. Quick to mount on drywall with the right anchors and ideal for displays in living rooms, kitchens and bedrooms.', 20.00, 'HOME-012', ARRAY[]::text[], ARRAY['Natural Oak'], ARRAY['/images/81zFxsbVQzL._AC_SL1500_.jpg','/images/81SN1ApOXkL._AC_SL1500_.jpg','/images/71k4cDZS49L._AC_SL1500_.jpg','/images/71iFhDjkXVL._AC_SL1500_.jpg'], 50, 'active', 'all', false, false, false),
