('chenille-bathroom-rug', 'Chenille Bathroom Rug', 'home-living', 'Textiles', 'Ultra-soft, highly absorbent chenille bath mat.', 'A soft chenille bath mat that is highly absorbent and extra comfortable underfoot. Measures 17 by 24 inches with a non-slip backing.', 8.99, 'HOME-015', ARRAY[]::text[], ARRAY['White'], ARRAY['/images/71duObz-4PL._AC_SL1500_.jpg','/images/71E-7KvJfYL._AC_SL1500_.jpg','/images/71eheT82SPL._AC_SL1500_.jpg','/images/71TMXHlAwLL._AC_SL1500_.jpg'], 50, 'active', 'all', false, false, false),
('queen-4-piece-luxury-bed-sheet-set', 'Queen 4-Piece Luxury Bed Sheet Set', 'home-living', 'Textiles', 'Breathable, silky soft queen sheet set with deep pockets.', 'A queen 4-piece sheet set with a silky, breathable finish. Everyday bedding essential with broad appeal.', 24.99, 'HOME-016', ARRAY[]::text[], ARRAY['Blue Stripe'], ARRAY['/images/81EFTtgevvL._AC_SL1500_.jpg','/images/81JgfBt-HoL._AC_SL1500_.jpg','/images/81WiTtRQcqL._AC_SL1500_.jpg','/images/915Z5FItVaL._AC_SL1500_.jpg'], 50, 'active', 'all', false, false, false),
